CATEGORIES = {
 "Device industry": ("Device Industry", "Typically medical device manufacturers and developers, or people writing from that perspective."),
 "Health professional": ("Health Professional", "Typically clinicians and other health care workers."),
 "Individual": ("Individual Consumer", "People commenting in a personal capacity."),
 "Private industry (non-device)": ("Private Industry", "Companies outside the device industry, such as AI, software, and consulting firms."),
 "Academia": ("Academia", "Universities, research institutes, and academic researchers."),
 "Health care association": ("Health Care Association", "Professional and trade associations in health care."),
 "Drug industry": ("Drug Industry, Drug Association", "Pharmaceutical companies and associations. The two Regulations.gov categories are combined here."),
 "Other": ("Other Organizations", "Organizations that chose none of the more specific categories."),
 "Government": ("Federal Government", "Federal agencies or their staff."),
 "International industry": ("International Industry", "Companies based outside the United States."),
}
THEMES = {
 "Reliance, sycophancy, and affective harms": "Users coming to depend on AI, AI telling users what they want to hear, and emotional harms.",
 "Hallucination and output reliability": "Made-up or inconsistent output, and outputs that drift or change between runs.",
 "Runtime controls and kill switches": "Controls that limit or stop a device while it runs, such as permission checks, hard limits, and off switches.",
 "Audit trails, provenance, and records": "Records that show what a device did, with which model version, and based on what sources.",
 "Cybersecurity": "Attacks on devices, including prompt injection, and the integrity of their inputs.",
 "Privacy and consent": "Protecting patient data, limits on its use, and patient consent.",
 "Liability and accountability": "Who is legally responsible when AI contributes to harm, and how accountability is enforced.",
 "Equity, access, and disability": "Performance across populations, access to care, and users with disabilities.",
 "Human oversight and automation bias": "Whether human review works in practice, including clinicians over-trusting AI and clinician workload.",
 "Small developer burden": "Costs and requirements that fall hardest on small companies.",
 "Coverage and reimbursement": "Insurance coverage and payment for AI-enabled care.",
 "Deployment settings and infrastructure": "Where and how devices run, such as hospitals, homes, offline settings, and local validation.",
 "Transparency and public participation": "Disclosure to patients and the public, labeling, and involving stakeholders in oversight.",
 "Regulatory process and harmonization": "Regulatory pathways, standards, terminology, and coordination with other agencies and countries.",
 "Opposition to AI use": "Objections to using generative AI in health care at all.",
 "Other": "Specialty-specific or one-off topics that fit no other theme.",
}
STANCE = {
 "support": "Endorses the proposal as described, or with minor tweaks.",
 "conditional": "Supports the proposal only with substantial conditions, limits, or safeguards the comment treats as necessary.",
 "oppose": "Argues against the proposal, says it is insufficient or inappropriate, or calls for a materially different approach.",
}
out = {
 "q": {str(n): {"title": f"Question {n}", "quote": t} for n, t in Q.items()},
 "sec": {k: {"title": a, "body": b} for k, (a, b) in SECTIONS.items()},
 "pos": {k: {"title": f"Question {n}", "quote": q, "body": b} for k, (n, q, b) in PROPOSALS.items()},
 "cat": {k: {"title": f"Regulations.gov category: {a}", "body": b + " Commenters choose their own category from a list when they submit, and FDA does not publish definitions for these categories. This description is ours."} for k, (a, b) in CATEGORIES.items()},
 "theme": {k: {"body": v} for k, v in THEMES.items()},
 "stance": {k: {"body": v} for k, v in STANCE.items()},
}
json.dump(out, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "tooltips.json"), "w"), indent=1, ensure_ascii=False)
print("ok")
